u32 getChannelScaledValue(M2C_UNK);                         /* extern */

/* Rescales *value in place: (*value << 16) divided by a rate from getChannelScaledValue(param), times 1000, then >> 5. */ void scaleValueByOutputRate(u32 *value, M2C_UNK param) {
    *value = (u32) (((u32) (*value << 0x10) / getChannelScaledValue(param)) * 0x3E8) >> 5;
}
